local config = {
  ui_story_30210601_1_dialog_content = "<color=#e8d9bb>Ciprat, ciprat</color>",
  ui_story_30210601_2_dialog_content = "Tempat ini benar-benar... terpencil.",
  ui_story_30210601_3_dialog_content = "Tapi melihat semua mawar ini mengapung di laut adalah pemandangan yang cukup menakjubkan...",
