  ui_story_30210601_5_dialog_content = "<color=#e8d9bb>Ciprat, ciprat</color>",
  ui_story_30210601_6_dialog_content = "Ah, ketemu...",
  ui_story_30210601_7_dialog_content = "<color=#e8d9bb>Jola berbaring tenang di atas batu, sepi seperti kelopak yang terapung di laut.</color>",
  ui_story_30210601_8_dialog_content = "<color=#e8d9bb>Seolah-olah ombak lembut bisa menyapunya pergi ke arus laut...</color>",
  ui_story_30210601_9_dialog_content = "Sungguh pemandangan...",
  ui_story_30210601_10_dialog_content = "Bukankah ini sedikit berbahaya?",
  ui_story_30210601_11_dialog_content = "Hah? Apakah itu kamu, PlayerName?",
