  ui_story_30210601_13_dialog_content = "Eh... sejujurnya...",
  ui_story_30210601_14_dialog_content = "Hanya karena ada yang mengeluh tentang \"seni avant-garde\"mu di Colossus, aku datang ke tempat ini!",
  ui_story_30210601_15_dialog_content = "Ah... apakah kamu berbicara tentang <color=#FFB400>pagar</color>? Jangan terlalu khawatir tentang hal kecil itu.",
  ui_story_30210601_16_dialog_content = "Orang-orang yang tidak mengerti seni dan cinta... mereka hanya memiliki sedikit prasangka terhadap saya.",
  ui_story_30210601_17_dialog_content = "Tapi, yang lebih penting…",
  ui_story_30210601_18_dialog_content = "Mari dan rasakan keindahan bunga-bunga layu ini bersamaku!",
  ui_story_30210601_19_dialog_content = "Namun…",
  ui_story_30210601_20_dialog_content = "Tidak ada \"tapi,\" PlayerName.",
  ui_story_30210601_21_dialog_content = "Jika hati kita beresonansi, mungkin saya akan mengerti keinginan mendesakmu untuk menangani pengaduan ini.",
