  ui_story_30210601_23_dialog_content = "Hanya ada cukup ruang untuk satu lagi di batu-batu ini. Tolong, ayo datang ke sini.",
  ui_story_30210601_24_dialog_content = "(Erm... Yah, saya rasa saya tahu Jola tidak akan mudah untuk dibujuk...)",
  ui_story_30210601_25_dialog_content = "(Aku akan ikut saja dengannya untuk sementara ini dan melihat apa yang terjadi.)",
  ui_story_30210601_26_dialog_content = "A... Aku paham sekarang.",
