  ui_story_30210601_32_dialog_content = "Siap!",
  ui_story_30210601_33_dialog_content = "<color=#e8d9bb>Angin laut mengangkat ombak yang berkilauan, membawa kesejukan langka ke kulit di udara musim panas.</color>",
