  ui_story_30210601_42_dialog_content = "Untuk lebih tepatnya, tema dari seni ini adalah \"Keindahan Momen Sementara.\"",
  ui_story_30210601_43_dialog_content = "Meskipun kelopak-kelopak ini mengapung di atas ombak dan laut azure membentuk pemandangan yang menakjubkan...",
