  ui_story_30210601_45_dialog_content = "Meskipun mereka beruntung tidak tenggelam, layu tidak akan membutuhkan waktu lama untuk menyerang mereka, berada di laut tanpa tanah dan nutrisi.",
  ui_story_30210601_46_dialog_content = "Tapi inilah mekarnya sebelum kematian dan putus asa... ah...",
  ui_story_30210601_47_dialog_content = "Cinta dan kerinduan terakhir itu, intens dan membara, seolah-olah meluap dari hati!",
  ui_story_30210601_48_dialog_content = "Bisakah kamu merasakannya?",
  ui_story_30210601_49_dialog_content = "Kalau memikirkannya dari perspektif ini...",
  ui_story_30210601_50_option_content = "Ini cukup disayangkan.",
  ui_story_30210601_51_dialog_content = "Menyesal... Hah...",
  ui_story_30210601_52_dialog_content = "Ini hanyalah takdir dari semua hal.",
  ui_story_30210601_53_dialog_content = "Meski kamu menyesal, tak ada yang bisa diubah.",
  ui_story_30210601_54_option_content = "Sungguh mengecewakan.",
  ui_story_30210601_55_dialog_content = "Putus asa? Uh-hmm...",
  ui_story_30210601_56_dialog_content = "Sepertinya kamu agak memahami kekejaman yang melekat, PlayerName.",
  ui_story_30210601_57_dialog_content = "Tapi, aku berharap kamu juga bisa melihat keindahan di dalam keputusasaan ini.",
  ui_story_30210601_58_dialog_content = "Uh... Oke? Mungkin insting artistikku memang tidak bisa dibandingkan dengan milikmu, Jola...",
  ui_story_30210601_59_dialog_content = "Tidak... ini bukan alasannya.",
  ui_story_30210601_60_dialog_content = "Pengalaman orang berbeda-beda, begitu juga emosi yang mereka rasakan.",
  ui_story_30210601_61_dialog_content = "Dan apa yang membangkitkan emosi kuat dalam diriku? Mungkin itu adalah kenangan masa kecilku.",
  ui_story_30210601_62_dialog_content = "Apakah sesuatu... serupa terjadi pada dirimu saat masih kecil?",
  ui_story_30210601_63_dialog_content = "Ah, tidak ada yang serius, jangan hiraukan aku...",
  ui_story_30210601_64_dialog_content = "Bahkan di masa kecilku, aku sering merasakan keindahan dan kebahagiaan yang menghibur.",
  ui_story_30210601_65_dialog_content = "Seperti hari-hari yang saya habiskan berkebun dengan saudariku di halaman tenang panti asuhan.",
  ui_story_30210601_66_dialog_content = "Sinar matahari siang yang hangat, bunga-bunga yang mekar di dalam pagar, dan senyuman yang paling indah...",
  ui_story_30210601_67_dialog_content = "Kakakmu...",
  ui_story_30210601_68_dialog_content = "Hari-hari lama telah memudar, tetapi keindahan yang aku rasakan saat itu masih ada di pikiranku.",
  ui_story_30210601_69_dialog_content = "Maksudmu... indahnya melakukan apa yang kamu suka bersama orang yang kamu cintai?",
  ui_story_30210601_70_dialog_content = "Tidak, tunggu, itu akan bertentangan dengan tema dari seni <color=#FFB400>ini</color>...",
  ui_story_30210601_71_dialog_content = "Ah, kamu cukup tajam, PlayerName. Saya senang.",
  ui_story_30210601_72_dialog_content = "Kecantikan yang kamu bicarakan memang merupakan kenangan yang tak terhapus bagi saya.",
  ui_story_30210601_73_dialog_content = "Namun setelah adikku pergi, waktu dan semua sensasiku seakan-akan membeku...",
  ui_story_30210601_74_dialog_content = "Melihat ladang bunga di dalam pagar, saya terlarut dalam renungan yang dalam.",
  ui_story_30210601_75_dialog_content = "Bunga-bunga indah yang ditanam bersama oleh saudaraku dan aku...",
  ui_story_30210601_76_dialog_content = "Mengapa mereka masih bisa bermekaran di halaman setelah dia pergi?",
  ui_story_30210601_77_dialog_content = "Mungkin karena... mereka dirawat terlalu baik sebelum waktu itu?",
  ui_story_30210601_78_dialog_content = "Jadi aku mengawasi mereka siang dan malam, saat mereka layu dan jatuh di halaman...",
  ui_story_30210601_79_dialog_content = "Itu benar-benar menjijikkan.",
  ui_story_30210601_80_dialog_content = "Tapi suatu hari, saat aku sedang mengumpulkan kelopak-kelopak bunga sendirian, aku mendapatkan pencerahan! Keindahan bunga-bunga di masa lalu—",
  ui_story_30210601_81_dialog_content = "Ketenangan dan kebahagiaan itu mekar dari teman-temanku saudariku.",
  ui_story_30210601_82_dialog_content = "Tetapi... ketika dia pergi, kecantikan itu secara alami layu.",
  ui_story_30210601_83_dialog_content = "Namun sengatan, kesedihan, dan rasa tak berdaya yang datang dengan layu... bukankah itu juga cara bagi mereka untuk menyampaikan keindahan?",
  ui_story_30210601_84_dialog_content = "Sepertinya kepergian saudaramu sangat memukulmu...",
  ui_story_30210601_85_dialog_content = "Pukulan? Tidak, tidak... peristiwa ini telah membuka mataku tentang keabadian seni.",
  ui_story_30210601_86_dialog_content = "Bunga-bunga berjuang di ambang layu untuk memancarkan vitalitas abadi, aroma mereka begitu mempesona...",
  ui_story_30210601_87_dialog_content = "Ini adalah pesona cinta dan kematian... pesona keinginan bodoh akan keabadian...",
  ui_story_30210601_88_dialog_content = "Berbicara tentang itu, PlayerName, apakah kamu percaya dengan kemungkinan cinta abadi di dunia ini?",
  ui_story_30210601_89_dialog_content = "Abadi?",
  ui_story_30210601_90_dialog_content = "Tapi bukankah kita baru saja mengagumi... keindahan layu?",
  ui_story_30210601_91_dialog_content = "Ya, kecantikan... kecantikan bisa ditingkatkan.",
  ui_story_30210601_92_dialog_content = "Dan ketinggian ini adalah hasil langsung dari kedatanganmu.",
  ui_story_30210601_93_dialog_content = "Sementara menyaksikan layu dan kehilangan ini dalam siklus tak berujung, bertemu dengan dirimu yang baru telah menjadi kejadian yang benar-benar berharga.",
  ui_story_30210601_94_dialog_content = "Jadi, bolehkah saya meminta kamu untuk menerima hadiah ini?",
  ui_story_30210601_95_dialog_content = "Huh? Hadiah?",
  ui_story_30210601_96_dialog_content = "Ini adalah karya terbaik yang paling memuaskan belakangan ini, sebuah mawar hati emas. Saya menyebutnya \"Caelum.\"",
  ui_story_30210601_97_dialog_content = "Begitukah...",
  ui_story_30210601_98_dialog_content = "Saya menawarkannya kepada Anda, bersama dengan cintaku. Maukah Anda menerimanya?",
  ui_story_30210601_99_dialog_content = "Durinya telah dihilangkan.",
  ui_story_30210601_100_dialog_content = "Ini mewakili fakta bahwa cinta ini tidak akan menyakitimu sedikit pun.",
  ui_story_30210601_101_dialog_content = "Akar-akarnya juga telah dicabut.",
  ui_story_30210601_102_dialog_content = "Ini mewakili fakta bahwa cinta ini tidak akan pernah lari. Ini akan selamanya menemani kamu dalam bentuknya yang sekarang, sempurna.",
  ui_story_30210601_103_dialog_content = "Tapi... jika itu masalahnya, bukankah terasa seperti Caelum adalah...",
  ui_story_30210601_104_dialog_content = "Agak menyedihkan?",
  ui_story_30210601_105_dialog_content = "Bagaimana bisa begitu, PlayerName? Kamu benar-benar memiliki simpati berlebih yang tidak perlu.",
  ui_story_30210601_106_dialog_content = "Anggota tubuh yang hilang ini tidak berarti dibandingkan dengan cinta abadi.",
  ui_story_30210601_107_dialog_content = "Jika ditawarkan kepada saya, saya <color=#FFB400>pasti</color> tidak akan menolak cinta seperti itu.",
  ui_story_30210601_108_dialog_content = "Yah, aku tidak begitu mengerti hal-hal dalam skala abadi, tapi untuk sekarang, sebagai seseorang yang hidup di masa kini...",
  ui_story_30210601_109_dialog_content = "Jika kita tidak menangani keluhan itu, akan ada masalah di Colossus!",
  ui_story_30210601_110_dialog_content = "Jadi, tentang pagar itu... Ah, apakah kamu sengaja memasangnya untuk membuatku datang mencarimu?",
  ui_story_30210601_111_dialog_content = "Haha, tolong jangan khawatir tentang itu. Saya tidak berniat memperluas pagar. Tentu saja, saya akan mengurusnya sesuai kebutuhan.",
  ui_story_30210601_112_dialog_content = "Jika kamu bisa memegang erat-erat cinta ini, apakah kamu di luar atau di dalam pagar, apa bedanya?",
  ui_story_30210601_113_dialog_content = "Topik tentang cinta ini... Aku masih belum begitu mengerti. Tapi bunga ini... Aku akan merawatnya, sungguh.",
  ui_story_30210601_114_dialog_content = "… Terima kasih.",
  ui_story_30210601_115_dialog_content = "Tapi sebelum kembali ke Colossus, bisakah kamu berbaring disini denganku sedikit lebih lama? Hanya sebentar saja.",
  ui_story_30210601_116_dialog_content = "Aku tidak bermaksud mengatakan bahwa kamu mirip dengan saudaraku, tapi dalam kebingungan ini, aku merasa seolah-olah...",
  ui_story_30210601_117_dialog_content = "Aku telah kembali ke sore yang tenang dan bahagia itu.",
  ui_story_30210601_118_dialog_content = "Aku tidak benar-benar mengerti semua yang kamu katakan sebelumnya...",
  ui_story_30210601_119_dialog_content = "Tapi kebahagiaan yang kamu bicarakan ini... Aku merasa itu adalah jenis hal yang bisa kamu temukan dalam menghargai pemandangan indah seperti ini.",
  ui_story_30210601_120_dialog_content = "Kita bisa kembali ke Colossus nanti.",
  ui_story_30210601_121_dialog_content = "Aku hanya akan menemanimu untuk saat ini... dan menikmati keindahan yang layu ini."
